    glyphs = {
        [1] = { item = 13642, side = 0, need = 8, icon = "Interface\\Icons\\INV_Inscription_MajorGlyph00", name = "Glyphe de l'Enclume", lore = "Frappé sur l'enclume de Khaz'goroth, il sonne encore quand on le serre.", description = "+3% de dégâts d'arme." },
        [2] = { item = 13643, side = 0, need = 10, icon = "Interface\\Icons\\INV_Inscription_MajorGlyph01", name = "Glyphe du Verdict", lore = "Tyr ne frappait qu'une fois. Il n'avait jamais besoin d'une deuxième.", description = "Vos bonus contre les ennemis presque morts (Coup de grâce, Exécuteur, Bénédiction de Tyr) se déclenchent plus tôt : 10% de vie en plus, jusqu'à 40%." },
        [3] = { item = 13644, side = 0, need = 10, icon = "Interface\\Icons\\INV_Inscription_MajorGlyph02", name = "Glyphe du Colosse", lore = "Les géants de fer d'Ulduar portaient ce signe gravé sur le poing.", description = "Vos attaques d'arme ont 3% de chances de frapper deux fois." },
        [4] = { item = 13645, side = 0, need = 8, icon = "Interface\\Icons\\INV_Inscription_MajorGlyph03", name = "Glyphe de la Forge ardente", lore = "Une braise de la Forge des volontés, prisonnière d'une rune.", description = "Vos attaques d'arme ont 8% de chances de vous donner +6% de dégâts d'arme pendant 8 s." },
        [5] = { item = 13646, side = 0, need = 6, icon = "Interface\\Icons\\INV_Inscription_MajorGlyph04", name = "Glyphe du Titan", lore = "Qui porte ce glyphe se tient comme une montagne se tient.", description = "+3% de points de vie maximum." },
        [6] = { item = 13647, side = 1, need = 8, icon = "Interface\\Icons\\INV_Inscription_MajorGlyph05", name = "Glyphe de la Curée", lore = "Chaque proie abattue nourrit la suivante.", description = "Chaque ennemi que vous tuez vous donne +400 puissance d'attaque pendant 15 s." },
        [7] = { item = 13648, side = 1, need = 10, icon = "Interface\\Icons\\INV_Inscription_MajorGlyph06", name = "Glyphe du Carnage", lore = "Odyn comptait ses guerriers à la hauteur de leur tas d'ennemis.", description = "Chaque ennemi que vous tuez a 30% de chances de vous donner +1% de dégâts d'arme pendant 15 s, jusqu'à 5 fois (+5%)." },
        [8] = { item = 13649, side = 1, need = 10, icon = "Interface\\Icons\\INV_Inscription_MajorGlyph07", name = "Glyphe de la Déflagration", lore = "Aggramar ne frappait jamais un démon seul.", description = "Vos attaques d'arme ont 8% de chances de toucher aussi jusqu'à 4 ennemis autour de votre cible, pour 15% des dégâts (au plus une fois toutes les 2 s)." },
        [9] = { item = 13650, side = 1, need = 8, icon = "Interface\\Icons\\INV_Inscription_MajorGlyph08", name = "Glyphe du Festin", lore = "Le sang versé revient toujours à celui qui l'a versé.", description = "2% des dégâts de vos attaques d'arme vous soignent." },
        [10] = { item = 13651, side = 1, need = 12, icon = "Interface\\Icons\\INV_Inscription_MajorGlyph09", name = "Glyphe de la Horde", lore = "Plus ils sont nombreux, plus le coup porte loin.", description = "Vos effets qui touchent plusieurs ennemis (Apothéose : Cataclysme, Bénédiction d'Aggramar, Glyphe de la Déflagration) en touchent 2 de plus." },
        [11] = { item = 13652, side = 2, need = 8, icon = "Interface\\Icons\\INV_Inscription_MajorGlyph10", name = "Glyphe du Miroir", lore = "Ce que l'on vous envoie vous appartient désormais.", description = "Quand vous êtes touché, 10% de chances de renvoyer 40% des dégâts à l'attaquant." },
        [12] = { item = 13653, side = 2, need = 10, icon = "Interface\\Icons\\INV_Inscription_MajorGlyph11", name = "Glyphe de l'Ombre", lore = "Taillé dans la nuit qui précède l'orage de Thorim.", description = "Vous subissez 2% de dégâts en moins." },
        [13] = { item = 13654, side = 2, need = 10, icon = "Interface\\Icons\\INV_Inscription_MajorGlyph12", name = "Glyphe des Lames jumelles", lore = "Deux éclairs ne tombent jamais au même endroit. Sauf ici.", description = "Vos attaques d'arme ont 3% de chances de frapper deux fois." },
        [14] = { item = 13655, side = 2, need = 8, icon = "Interface\\Icons\\INV_Inscription_MajorGlyph13", name = "Glyphe de la Saignée", lore = "La plus fine des lames laisse la plus longue des traces.", description = "2% des dégâts de vos attaques d'arme vous soignent." },
        [15] = { item = 13656, side = 2, need = 6, icon = "Interface\\Icons\\INV_Inscription_MajorGlyph14", name = "Glyphe du Vent", lore = "Golganneth y a soufflé la vitesse des tempêtes.", description = "+3% de dégâts d'arme." },
        [16] = { item = 13657, side = 3, need = 10, icon = "Interface\\Icons\\INV_Inscription_MajorGlyph15", name = "Glyphe du Rempart", lore = "Hodir a tenu seul une passe gelée contre une armée entière.", description = "Vous subissez 2% de dégâts en moins." },
        [17] = { item = 13658, side = 3, need = 8, icon = "Interface\\Icons\\INV_Inscription_MajorGlyph16", name = "Glyphe de Granit", lore = "Une écaille de la peau de pierre des premiers terrestres.", description = "+4% d'armure." },
        [18] = { item = 13659, side = 3, need = 10, icon = "Interface\\Icons\\INV_Inscription_MajorGlyph17", name = "Glyphe de Rancune", lore = "Chaque coup reçu est une dette. Celui-ci tient les comptes.", description = "Plus vous encaissez, plus vous frappez fort : 5% des dégâts subis ces dernières secondes s'ajoutent à votre puissance d'attaque et des sorts." },
        [19] = { item = 13660, side = 3, need = 6, icon = "Interface\\Icons\\INV_Inscription_MajorGlyph18", name = "Glyphe du Défi", lore = "Le rugissement gravé dans cette rune attire les regards, et les coups.", description = "+15% de menace générée." },
        [20] = { item = 13661, side = 3, need = 8, icon = "Interface\\Icons\\INV_Inscription_MajorGlyph19", name = "Glyphe de Vie", lore = "Forgé par Mimiron pour qu'une machine ne s'arrête jamais.", description = "+4% de points de vie maximum." },
        [21] = { item = 13662, side = 4, need = 10, icon = "Interface\\Icons\\INV_Inscription_MajorGlyph20", name = "Glyphe de Résonance", lore = "Norgannon y a écrit un mot qui ne cesse de se répéter.", description = "Vos coups critiques de sort ont 8% de chances de frapper à nouveau, pour 50% des dégâts." },
        [22] = { item = 13663, side = 4, need = 10, icon = "Interface\\Icons\\INV_Inscription_MinorGlyph00", name = "Glyphe de la Tempête", lore = "Un fragment de l'orage qui gronde au-dessus d'Ulduar.", description = "Vos sorts de dégâts ont 8% de chances de rebondir sur jusqu'à 3 ennemis proches, pour 20% des dégâts (au plus une fois par seconde)." },
        [23] = { item = 13664, side = 4, need = 8, icon = "Interface\\Icons\\INV_Inscription_MinorGlyph01", name = "Glyphe de Célérité", lore = "Le temps d'Aman'Thul s'y écoule un peu plus vite qu'ailleurs.", description = "Vos sorts ont 10% de chances d'accélérer vos incantations de 8% pendant 8 s." },
        [24] = { item = 13665, side = 4, need = 8, icon = "Interface\\Icons\\INV_Inscription_MinorGlyph02", name = "Glyphe de Puissance arcanique", lore = "Il brûle les doigts de ceux qui ne savent pas le lire.", description = "+3% de dégâts des sorts." },
        [25] = { item = 13666, side = 4, need = 12, icon = "Interface\\Icons\\INV_Inscription_MinorGlyph03", name = "Glyphe de la Singularité", lore = "Tout ce qui faiblit y est attiré, puis englouti.", description = "Vos bonus contre les ennemis presque morts (Désintégration, Bénédiction de Tyr) se déclenchent plus tôt : 10% de vie en plus, jusqu'à 40%." },
        [26] = { item = 13667, side = 5, need = 8, icon = "Interface\\Icons\\INV_Inscription_MinorGlyph04", name = "Glyphe de Sève", lore = "Une goutte de la rosée des jardins d'Eonar.", description = "+3% de soins prodigués par vos sorts." },
        [27] = { item = 13668, side = 5, need = 10, icon = "Interface\\Icons\\INV_Inscription_MinorGlyph05", name = "Glyphe du Partage", lore = "Freya ne gardait rien pour elle, pas même la vie.", description = "Quand vous êtes soigné, l'allié le plus blessé à moins de 30 mètres reçoit aussi 5% de ce soin." },
        [28] = { item = 13669, side = 5, need = 10, icon = "Interface\\Icons\\INV_Inscription_MinorGlyph06", name = "Glyphe de l'Égide", lore = "Une rune de garde que les Gardiens gravaient sur leurs portes.", description = "Vos sorts ont 10% de chances de vous entourer d'un bouclier pendant 8 s : il absorbe autant de dégâts que 80% de votre puissance des sorts (au plus une fois toutes les 20 s)." },
        [29] = { item = 13670, side = 5, need = 8, icon = "Interface\\Icons\\INV_Inscription_MinorGlyph07", name = "Glyphe de Clarté", lore = "L'esprit qui le porte ne connaît pas la fatigue.", description = "Vos sorts ont 8% de chances de vous rendre 2% de votre mana maximum (au plus une fois toutes les 6 s)." },
